/* Independent UI/UX review release, 2026-11-03. All executions are synthetic. */
(()=>{'use strict';
const C=PlazaCore,KEY='baic-independent-plaza-20261103',h=esc;
let lastSaved=localStorage.getItem(KEY);
let Q;try{Q=JSON.parse(lastSaved);if(Q?.schema!==1)Q=C.initial();}catch{Q=C.initial();}
EvaluationFlow.init(Q,allAssets());for(const o of Q.objects)for(const v of o.versions){v.bindings=v.bindings||(o.upstream==='pet-agent'?{event:'event-adapter@1',request:'standard-api@1.0'}:o.upstream==='office-agent'?{script:'program-adapter@1',request:'standard-api@1.0'}:{request:'standard-api@1.0'});}
let tab='AGENT',query='',pickerQuery='',detailId=Q.objects[0].id,detailVersion='',detailEnv='test',message='',busy=false;
const names={WAITING_REVIEW:'待复核',NEEDS_ATTENTION:'待处理',DRAFT:'草稿',READY:'待确认',BLOCKED:'待补齐',RUNNING:'运行中',COMPLETED:'已完成',CANCELLED:'已取消'};
const steps=['目标与对象','数据、用例与指标','运行前检查','确认与冻结','运行与证据','复核与报告'];
const B=(text,action,key='',style='',disabled=false)=>`<button class="btn ${style}" data-pz="${action}" data-key="${h(String(key))}" ${disabled?'disabled':''}>${text}</button>`;
const badge=(text,kind='')=>`<span class="pz-badge ${kind}">${h(text)}</span>`;
const notice=(text,kind='')=>`<div class="pz-notice ${kind}" role="status">${text}</div>`;
const panel=(title,body,extra='')=>`<section class="pz-panel"><div class="pz-panel-head"><h2>${title}</h2><div class="pz-actions">${extra}</div></div>${body}</section>`;
const field=(label,key,value='',hint='',attrs='')=>`<label class="pz-field">${label}<input data-pz-field="${key}" value="${h(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,key,options,value,hint='')=>`<label class="pz-field">${label}<select data-pz-field="${key}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select>${hint?`<small>${hint}</small>`:''}</label>`;
const sourceName=id=>C.SOURCES.find(s=>s.id===id)?.name||id;
const envName=id=>C.ENVIRONMENTS.find(s=>s.id===id)?.name||'待选择';
const kv=rows=>`<dl class="pz-kv">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
const table=(heads,rows)=>`<div class="pz-table-wrap"><table class="pz-table"><thead><tr>${heads.map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function title(name,desc,action=''){return `<div class="pz-title"><div><div class="pz-kicker">北汽研究院 · AI 评测平台</div><h1>${name}</h1><p>${desc}</p></div><div class="pz-actions">${action}</div></div>`;}
function wrap(body){return `<div class="pz">${message?notice(h(message),'warn'):''}${body}<div class="pz-footer">独立交互评审版 · 2026.11.11 · 合成数据与验证结果 · 未连接真实被测服务</div></div>`;}
function persist({checkConflict=false}={}){
 if(checkConflict&&localStorage.getItem(KEY)!==lastSaved)throw Error('用例列表已在其他窗口更新，请刷新后重试。');
 const next=JSON.stringify(Q);
 localStorage.setItem(KEY,next);
 lastSaved=next;
}
function paint(){persist();render();}
function route(id){message='';persist();go(id);window.scrollTo(0,0);}
function openTask(id){
 if(!C.task(Q,id))throw Error('找不到任务 '+id+'，请从任务列表重新选择。');
 window.FlowUI?.clearReturnContext();Q.activeTask=id;pickerQuery='';route('task-prep');
}
function newTask(input={}){const t=C.createTask(Q,input);openTask(t.id);return t;}
function readiness(o){const ok=o.versions.some(v=>Object.values(v.checks).some(x=>x.ok));return badge(ok?'可选版本已验证':'待完成接入',ok?'good':'warn');}
function taskRows(){return Q.tasks.map(t=>[`${h(t.name)}<small>${h(t.id)}</small>`,h(C.object(Q,t.objectId)?.name||t.pending?.name||'对象待补齐'),badge(names[t.status],t.status==='COMPLETED'?'good':t.status==='BLOCKED'?'warn':''),B(t.status==='COMPLETED'?'查看报告':'继续准备','open-task',t.id,'ghost')]);}
function overview(){return wrap(title('工作概览','继续准备评测，或查看需要你处理的结果。',B('新建评测任务','new-task','','primary'))+panel('继续工作',table(['任务','被测对象','状态','操作'],taskRows()),B('全部任务','go','tasks','ghost'))+`<div class="pz-grid">${panel('接入被测对象','<p class="muted">在广场管理 Agent、应用与模型的固定版本和接入状态。</p>',B('打开广场','go','plaza','ghost'))}${panel('准备评测材料','<p class="muted">在资产中心管理测试数据、功能用例、指标与评分规则。</p>',B('打开资产中心','go','assets','ghost'))}</div>`);}
const inheritedTasks=pages.tasks,inheritedRuns=pages.runs,inheritedResources=pages.resources;
function tasks(){return wrap(title('评测任务','准备材料、运行评测，再查看带证据的结果。',(window.MultiEnvUI?.planButton()||'')+(window.FrameworkEvaluationUI?.templateButton()||'')+B('新建评测任务','new-task','','primary'))+panel('任务列表',table(['任务','被测对象','状态','操作'],taskRows()))+`<details><summary>查看既有任务记录</summary><div class="pz-inherit">下方保留基线任务及其原始规则；新增任务使用新版准备流程。</div>${inheritedTasks().replace(/<div class="prd-intro">[\s\S]*?<\/div><\/div>/,'')}</details>`);}
function gallery(){const os=Q.objects.filter(o=>o.visible&&o.project==='cockpit'&&o.type===tab&&(!query||[o.name,o.purpose,sourceName(o.source),o.owner].join(' ').toLowerCase().includes(query.toLowerCase())));return wrap(title('Agent/模型广场','选择被测对象，查看固定版本和接入状态，再发起评测。',B('接入对象','register','','primary',!Q.demo.canCreate))+`<div class="pz-tabs" role="tablist" aria-label="对象类型">${Object.entries(C.TYPES).map(([id,label])=>{const count=Q.objects.filter(o=>o.visible&&o.project==='cockpit'&&o.type===id).length;return `<button type="button" id="pz-tab-${id}" class="pz-tab" role="tab" aria-selected="${id===tab}" aria-controls="pz-object-results" tabindex="${id===tab?0:-1}" data-pz="tab" data-key="${id}">${ic({AGENT:'branch',APPLICATION:'grid',MODEL:'box'}[id])}<strong class="pz-tab-label">${label}</strong><small class="pz-tab-count">${count} 个</small></button>`;}).join('')}</div><div id="pz-object-results" role="tabpanel" aria-labelledby="pz-tab-${tab}" tabindex="0"><div class="pz-toolbar"><div class="pz-search">${ic('search')}<input aria-label="搜索广场对象" data-pz-field="galleryQuery" value="${h(query)}" placeholder="搜索名称、用途、来源或负责人"></div><span class="pz-version">当前项目 · 智能座舱评测</span></div>${!Q.demo.canCreate?notice('当前账号没有创建对象权限。可浏览已有对象；新增对象请联系项目管理员。','warn'):''}${os.length?`<div class="pz-grid">${os.map(o=>`<article class="pz-object"><div class="pz-object-top"><div class="pz-monogram ${o.type}">${o.type==='AGENT'?'AG':o.type==='MODEL'?'M':'APP'}</div><div><h3>${h(o.name)}</h3><small>${C.TYPES[o.type]}</small></div></div><p>${h(o.purpose)}</p><dl><dt>来源</dt><dd>${h(sourceName(o.source))}</dd><dt>负责人</dt><dd>${h(o.owner)}</dd></dl><div class="pz-object-foot">${readiness(o)}${B('查看详情','detail',o.id,'ghost')}</div></article>`).join('')}</div>`:`<div class="pz-empty"><h3>未找到可见对象</h3><p>可接入新对象，或请项目管理员核对对象权限。</p>${B('接入对象','register','','',!Q.demo.canCreate)}</div>`}</div>`);}
function validationView(report){if(!report)return notice('尚未验证此版本在所选执行环境中的可访问性。','warn');return notice(report.ok?'接入验证通过（演示）':'接入验证未通过（演示）',report.ok?'good':'bad')+kv([['执行环境',h(envName(report.environment))],['执行身份',`<code>${h(report.identity)}</code>`],['固定版本',h(report.version)],['验证时间',new Date(report.at).toLocaleString('zh-CN')]])+`<div style="margin-top:14px">${report.items.map(x=>`<div class="pz-check"><div><strong>${h(x.label)}</strong><small>${h(x.detail)}</small></div>${badge(x.ok===true?'通过':x.ok===false?'未通过':'未执行',x.ok===true?'good':x.ok===false?'bad':'')}</div>`).join('')}</div>`;}
function detail(){const o=C.object(Q,detailId);if(!o)return wrap(title('对象不可用','请重新选择你有权访问的对象。',B('返回广场','go','plaza','primary')));let v=C.version(o,detailVersion)||o.versions[0];detailVersion=v?.id||'';const report=v?.checks[detailEnv];return wrap(`<div class="pz-crumb">${B('Agent/模型广场','go','plaza','ghost')}<span>/</span><span>${h(o.name)}</span></div>`+title(h(o.name),h(o.purpose),B(report?.ok?'新建评测':'完成接入',report?.ok?'evaluate-object':'connect',o.id,'primary'))+`<div class="pz-split"><div>${panel('版本与运行环境',`<div class="pz-fields">${select('固定版本','detailVersion',o.versions.length?o.versions.map(v=>[v.id,v.label]):[['','暂无版本']],detailVersion)}${select('评测执行环境','detailEnv',C.ENVIRONMENTS.map(e=>[e.id,e.name]),detailEnv)}</div><p class="pz-target-note" style="margin-top:15px">同一对象的版本集中在这里管理。任务将绑定所选版本，不跟随最新版本自动变化。</p>`+kv([['来源系统',h(sourceName(o.source))],['来源对象',h(o.upstream)],['负责人',h(o.owner)],['调用方式',v?h(Object.values(v.bindings||{}).join(' / ')):'待接入负责人补齐'],['调用凭证',v?'已登记的授权引用 · 不显示密钥':'待补齐']]))}${window.FlowUI?FlowUI.objectBinding(o,v):''}${panel('接入验证',validationView(report),B('重新验证','connect',o.id,'ghost'))}</div><aside class="pz-side">${panel('本次可做什么',`<p>接入验证通过后，可使用该版本创建评测。</p><p class="muted">开始评测时还会检查调用权限、数据、用例、指标及环境。</p>${v?.modelRef?`<hr><p>关联模型</p>${B(h(C.object(Q,v.modelRef)?.name||'关联模型'),'detail',v.modelRef,'ghost')}`:''}`)}</aside></div>`);}
function creation(){const r=Q.registration;if(!r)return wrap(title('接入对象','选择一种对象类型开始。',B('返回广场','go','plaza','primary')));const t=C.task(Q,r.taskId),c=C.availableCatalog(r),o=C.object(Q,r.objectId);const connected=Q.demo.sourceConnected&&C.SOURCES.find(x=>x.id===r.source)?.connected;return wrap(`<div class="pz-crumb">${B(t?'返回原任务':'返回广场',t?'save-return':'go',t?'':'plaza','ghost')}<span>/</span><span>接入对象</span></div>`+title(t?'为评测接入对象':'接入对象',t?`${t.id} · 已自动保存草稿，完成后返回并保留已选材料。`:'登记一次后，可在广场与评测任务中复用。')+`<nav class="pz-stepper two" aria-label="接入步骤"><button class="pz-step" data-pz="reg-step" data-key="0" ${r.step===0?'aria-current="step"':''}><b>1</b>登记对象</button><button class="pz-step" disabled ${r.step===1?'aria-current="step"':''}><b>2</b>完成接入</button></nav>${r.error?notice(h(r.error),'bad'):''}${!Q.demo.canCreate?notice('当前账号没有创建对象权限。所需权限：项目内创建对象；负责角色：项目管理员。仍可保存任务草稿。','warn'):''}`+(r.step===0?panel('登记对象',`<div class="pz-radio"><label><input type="radio" name="pz-method" data-pz-field="reg.method" value="source" ${r.method==='source'?'checked':''}>从已连接来源选择</label><label><input type="radio" name="pz-method" data-pz-field="reg.method" value="manual" ${r.method==='manual'?'checked':''}>手工登记</label></div><div class="pz-fields">${select('对象类型','reg.type',Object.entries(C.TYPES),r.type)}${select('来源系统','reg.source',C.SOURCES.map(s=>[s.id,s.name+(s.connected?'':'（待连接）')]),r.source)}${r.method==='source'?`<div class="pz-full">${connected?select('来源中的对象','sourceObject',[['','请选择来源对象'],...C.CATALOG.filter(x=>x.source===r.source&&x.type===r.type).map(x=>[x.id,x.name])],r.upstream,'名称、负责人及已有版本会自动带入。'):notice('来源系统未连接。请由接入负责人在“资源与接入”完成连接后继续；可以先保存。','warn')}</div>`:''}${field('对象名称','reg.name',r.name,'必填；不完整时可以先保存任务草稿。')}${r.method==='manual'?field('来源对象标识','reg.upstream',r.upstream,'填写来源系统中的真实标识，不使用平台临时编号。'):field('来源对象标识','read',r.upstream,'由来源目录取得。','readonly')}${field('负责人','reg.owner',r.owner)}${field('所属项目','read','智能座舱评测','由任务带入。','readonly')}<label class="pz-field pz-full">用途<textarea data-pz-field="reg.purpose">${h(r.purpose)}</textarea></label></div><div class="pz-bottom"><small>满足必需信息后建立正式对象记录；版本在下一步选择。</small><div class="pz-actions">${B('保存并稍后补齐','save-return')}${B('下一步：完成接入','register-next','','primary',!Q.demo.canCreate)}</div></div>`):panel('完成接入',`<div class="pz-chip"><div><strong>${h(o?.name||r.name)}</strong><small>${h(C.TYPES[r.type])} · ${h(sourceName(r.source))} · ${h(r.owner)}</small></div>${badge(r.reused?'复用已有对象':'已登记','info')}</div><div class="pz-fields" style="margin-top:20px">${select('固定版本','reg.versionLabel',c?c.versions.map(v=>[v,v]):[['','暂无已登记版本']],r.versionLabel)}${select('评测执行环境','reg.environment',C.ENVIRONMENTS.map(e=>[e.id,e.name]),r.environment)}${field('已登记的调用方式','read',c?(Object.values(o?.versions.find(v=>v.label===r.versionLabel)?.bindings||{}).join(' / ')||'标准 API · standard-api@1.0'):'待补齐','由版本记录自动带入。','readonly')}${field('授权凭证','read',c?'已授权凭证 · '+sourceName(r.source):'待补齐','仅使用凭证引用，不展示明文密钥。','readonly')}</div>${!c?notice('此来源对象尚无已登记版本和调用配置。请接入负责人补齐；本页保留登记结果。','warn'):notice('验证将在所选评测执行环境中，以实际执行身份检查连通、鉴权、固定版本与返回格式。你的电脑能打开地址不能作为通过依据。')}<p class="pz-target-note">当前评审页只演示验证状态，不会发起真实调用。</p>${window.FlowUI?FlowUI.connectionLink(r):''}${r.result?validationView(r.result):''}${busy?notice('正在验证 · 连通 → 鉴权 → 版本识别 → 输入输出格式…'):''}<div class="pz-bottom"><small>返回后仍需完成任务运行前检查。</small><div class="pz-actions">${B('保存并稍后补齐','save-return','','',busy)}${B(r.result&&!r.result.ok?'修改接入信息':'上一步','reg-step','0','ghost',busy)}${B(t?(r.result&&!r.result.ok?'重新验证并返回评测':'验证并返回评测'):'验证接入','validate','','primary',busy||!c||!Q.demo.canCreate)}</div></div>`)));}
function picker(t){const o=C.object(Q,t.objectId),v=C.version(o,t.versionId),pinned=t.materials.suite;if(o)return `<div class="pz-chip"><div><strong>${h(o.name)}</strong><small>${h(C.TYPES[o.type])} · ${h(sourceName(o.source))} · ${h(o.owner)}</small></div>${pinned?badge('来自评测套件','info'):B('更换','clear-object','','ghost')}</div><div class="pz-fields" style="margin-top:17px">${select('固定版本','task.versionId',o.versions.length?o.versions.map(v=>[v.id,v.label]):[['','暂无版本']],t.versionId)}${pinned?field('执行环境','read',envName(t.environment),'','readonly'):select('执行环境','task.environment',C.ENVIRONMENTS.map(e=>[e.id,e.name]),t.environment)}</div><div class="pz-bottom"><span>${v?.checks[t.environment]?.ok?badge('接入验证通过（演示）','good'):badge('待完成接入','warn')}</span>${B('完成接入','connect-task',o.id,'ghost')}</div>`;
 const os=Q.objects.filter(o=>o.visible&&o.type===t.type&&(!window.NavigationUI||NavigationUI.availableObject(o))&&(!pickerQuery||o.name.includes(pickerQuery)));return `${Object.keys(t.pending||{}).length?notice(`对象待补齐${t.pending.name?'：'+h(t.pending.name):''}。数据、用例和指标已保留。 ${B('继续补齐','resume','','ghost')}`,'warn'):''}<div class="pz-fields">${select('对象类型','task.type',Object.entries(C.TYPES),t.type)}<label class="pz-field">被测对象<input data-pz-field="pickerQuery" aria-label="搜索被测对象" value="${h(pickerQuery)}" placeholder="搜索广场中的对象"></label></div><div class="pz-toolbar" style="margin-top:16px"><small>仅显示当前项目内你有权选择的对象。</small>${B('新建对象','register-task','','ghost',!Q.demo.canCreate)}</div>${os.length?`<div class="pz-options">${os.map(o=>`<button class="pz-option" data-pz="select-object" data-key="${h(o.id)}"><span><strong>${h(o.name)}</strong><small>${h(sourceName(o.source))} · ${h(o.owner)}</small></span>${readiness(o)}</button>`).join('')}</div>`:`<div class="pz-empty"><h3>未找到可选对象</h3><p>可新建对象或稍后补齐。已有对象未显示时，请项目管理员核对权限。</p><div class="pz-actions">${B('新建对象','register-task','','',!Q.demo.canCreate)}${B('稍后补齐','defer-object','','ghost')}</div></div>`}${!Q.demo.canCreate?notice('当前账号没有创建对象权限，请联系项目管理员。仍可保存草稿并准备其他材料。','warn'):''}`;}
function taskPage(){const t=C.task(Q);if(!t)return wrap(title('选择评测任务','从任务列表继续。',B('打开任务列表','go','tasks','primary')));if(t.frameworkPlan&&window.FrameworkEvaluationUI)return FrameworkEvaluationUI.taskPage(t);if(t.suitePlan&&window.MultiEnvUI)return MultiEnvUI.taskPage(t);const o=C.object(Q,t.objectId),locked=!!t.run;return wrap(`<div class="pz-crumb">${B('评测任务','go','tasks','ghost')}<span>/</span><span>${h(t.id)}</span></div>`+title(h(t.name),`${names[t.status]} · ${o?h(o.name):'对象待补齐'} · ${t.savedAt?'内容已保存':'草稿自动保存'}`,B('保存草稿','save-task','','',locked))+`<nav class="pz-stepper" aria-label="评测步骤">${steps.map((name,i)=>`<button class="pz-step" data-pz="task-step" data-key="${i}" ${i===t.step?'aria-current="step"':''}><b>${i+1}</b><span>${name}</span></button>`).join('')}</nav>`+taskStep(t));}
function taskStep(t){const o=C.object(Q,t.objectId),v=C.version(o,t.versionId);switch(t.step){case 0:return `${t.run?notice('本次运行已冻结，以下内容只用于查看；如需修改，请新建评测。')+panel('目标与对象',kv([['评测目标',h(t.goal)],['被测对象',h(o?.name||'—')],['固定版本',h(v?.label||'—')]]),B('下一步','task-step','1','primary')):panel('这次要验证什么',`<div class="pz-fields">${field('任务名称','task.name',t.name)}${field('所属项目','read','智能座舱评测','','readonly')}<label class="pz-field pz-full">评测目标<textarea data-pz-field="task.goal" placeholder="说明场景、要检查的行为和预期结果">${h(t.goal)}</textarea></label></div><details style="margin-top:14px"><summary>关联需求（可选）</summary>${field('需求链接或编号','task.requirement',t.requirement,'已有需求可直接引用。')}</details>`)+panel('被测对象',picker(t))+`<div class="pz-bottom"><small>对象可以稍后补齐；未就绪时不能开始在线执行。</small>${B('下一步：准备材料','task-step','1','primary')}</div>`}`;
case 1:if(window.FlowUI)return FlowUI.materials(t);return panel('选择本次评测材料',`<p class="muted">选择已发布的固定版本。更换对象类型后会重新检查兼容性。</p>${[['data','测试数据','输入样本及独立参考结果'],['cases','功能测试用例',t.type==='MODEL'?'当前模型任务可选；需要验证交互行为时添加。':'动作、断言与运行后采集的证据要求'],['metrics','指标与评分规则','评分方法、阈值与复核条件']].map(([k,n,d])=>`<div class="pz-material"><div><h3>${n}</h3><p>${d}</p></div><div>${select(n+'版本','material.'+k,[['','请选择'],...C.MATERIALS[k].filter(x=>x.types.includes(t.type)).map(x=>[x.id,x.name+' · '+x.version])],t.materials[k])}</div></div>`).join('')}<p class="pz-target-note">在线执行由运行环节产出用例执行结果；不要求在开始前填写结果。已有离线结果须按原证据导入规则绑定用例、对象版本和执行来源。</p><div class="pz-bottom">${B('管理评测材料','go','assets','ghost')}${B('下一步：运行前检查','task-step','2','primary')}</div>`);
case 2:if(window.FlowUI)return FlowUI.preflight(t);{const checks=t.preflight?.checks||C.taskChecks(Q,t);return panel('运行前检查',notice('接入验证只证明对象当时可调用。这里再次核对当前任务所需的权限、版本、环境和材料。')+table(['检查项','结果与原因','负责角色','操作'],checks.map(x=>[h(x.name),badge(x.ok?'已就绪':'待补齐',x.ok?'good':'warn')+`<small>${h(x.detail)}</small>`,h(x.owner),x.ok?'—':B('去补齐','repair',x.key,'ghost')]))+notice('原有预算、独立参考保护、执行器资格与清理策略门槛继续有效。评审原型仅回放界面状态，真实放行需服务端完成这些检查。','warn')+`<div class="pz-bottom"><small>${t.preflight?'上次检查：'+new Date(t.preflight.at).toLocaleString('zh-CN'):'尚未运行检查'}</small><div class="pz-actions">${B('重新检查','preflight')}${B('检查并继续','preflight-next','','primary',!!t.run)}</div></div>`);}
case 3:return (window.FlowUI?FlowUI.manifest(t):'')+panel('确认本次评测',kv([['评测目标',h(t.goal||'待补齐')],['对象版本',h((o?.name||'待补齐')+' · '+(v?.label||'待补齐'))],['执行环境',h(envName(t.environment))],['测试数据',h(C.MATERIALS.data.find(x=>x.id===t.materials.data)?.name||'待补齐')],['用例 / 指标',h([(t.caseRefs||[]).map(k=>EvaluationFlow.get(Q.flow,k)?.name).filter(Boolean).join('、'),C.MATERIALS.metrics.find(x=>x.id===t.materials.metrics)?.name].filter(Boolean).join(' / '))]])+`<div style="margin-top:20px">${['engineer','business'].map(role=>`<div class="pz-check"><div><strong>${role==='engineer'?'林工 · 评测负责人':'赵经理 · 业务负责人'}</strong><small>${t.confirmations[role]?'已确认当前方案':'待确认；两位负责人须为不同账号'}</small></div>${t.confirmations[role]?badge('已确认','good'):B('确认当前方案','confirm',role,'',S.role!==role||!!t.run)}</div>`).join('')}</div><div class="pz-bottom"><small>在顶部切换演示角色完成两人确认。冻结后引用不变；执行前仍复检。</small>${B('冻结并开始演示评测','start','','primary',!t.confirmations.engineer||!t.confirmations.business||!!t.run||S.role!=='engineer')}</div>`);
case 4:if(window.FlowUI)return FlowUI.execution(t);return panel('运行与证据',!t.run?notice('先完成运行前检查和两位负责人确认。','warn')+B('返回确认','task-step','3','primary'):`${badge(names[t.status],t.status==='COMPLETED'?'good':'info')}<div class="pz-progress"><span style="width:${t.run.progress}%"></span></div>${kv([['运行编号',h(t.run.id)],['固定版本',h(v?.label||'—')],['运行模式','合成回放 · 不访问真实服务']])}<div class="pz-log">${t.run.events.map(x=>`<p>${h(x)}</p>`).join('')}</div>${t.result?`<div class="pz-bottom"><small>原始合成记录与固定引用随报告保存。</small>${B('查看复核与报告','task-step','5','primary')}</div>`:`<div class="pz-bottom"><small>当前模拟执行与证据采集。</small>${B('取消演示运行','cancel')}</div>`}`);
case 5:if(window.FlowUI)return FlowUI.results(t);return panel('复核与报告',!t.result?notice('完成运行后查看结果；未完成时不会生成通过结论。','warn')+B('查看运行状态','task-step','4','primary'):`${notice('评测已完成 · 存在 2 项待处理问题','warn')}<div class="pz-stats"><div class="pz-stat"><strong>${t.result.executed}</strong><small>已执行用例</small></div><div class="pz-stat"><strong>${t.result.passed}</strong><small>符合规则</small></div><div class="pz-stat"><strong>${t.result.failed}</strong><small>未符合规则</small></div></div>${table(['问题','证据','处理'],t.result.issues.map((x,i)=>[h(x),`合成用例 ${i+1} · 对象 ${h(v?.label||'—')}`,badge('待处理','warn')]))}<details style="margin-top:20px"><summary>查看固定引用与合成证据</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px">${h(JSON.stringify({synthetic:true,run:t.run.frozen,issues:t.result.issues},null,2))}</pre></details><div class="pz-bottom"><small>结论仅用于交互评审。质量复核、快照与审计沿用原规则。</small>${B('导出评审结果','export','','primary')}</div>`);
default:return '';}}
function demoDialog(){let d=document.getElementById('pz-demo');if(d)d.remove();d=document.createElement('dialog');d.id='pz-demo';d.className='pz-demo-dialog';d.innerHTML=`<div class="pz"><h2>演示条件</h2><p class="muted">只影响本地合成流程，不改变真实账号或平台权限。</p><div class="pz-fields">${select('对象创建权限','demo.canCreate',[['true','允许创建'],['false','没有创建权限']],String(Q.demo.canCreate))}${select('来源系统连接','demo.sourceConnected',[['true','已连接'],['false','连接已失效']],String(Q.demo.sourceConnected))}${select('模拟验证结果','demo.failure',[['none','正常'],['network','地址不可达'],['auth','调用未授权'],['version','版本无法确认'],['schema','返回格式不匹配']],Q.demo.failure)}${select('运行前调用权限','demo.revoked',[['false','有效'],['true','已失效']],String(Q.demo.revoked))}${select('运行前版本','demo.drift',[['false','保持固定版本'],['true','版本已变化']],String(Q.demo.drift))}</div><div class="pz-actions">${B('重新开始示例','reset','','ghost')}${B('应用并关闭','close-demo','','primary')}</div></div>`;document.body.append(d);d.showModal();}
function registration(taskId=null,objectId=null){if(!taskId&&!objectId&&Q.registration&&!Q.registration.taskId){route('object-create');return;}const t=C.task(Q,taskId);C.beginRegistration(Q,{type:t?.type||tab,name:taskId?pickerQuery:query,taskId,objectId});route('object-create');}
function handle(action,key){const t=C.task(Q),r=Q.registration,suite=window.SuiteUI?.assetForTask(t);message='';try{switch(action){case 'go':route(key);return;case 'new-task':newTask();return;case 'open-task':openTask(key);return;case 'tab':tab=key;query='';paint();document.getElementById('pz-tab-'+key)?.focus();return;case 'detail':detailId=key;detailVersion='';detailEnv='test';route('object-detail');return;case 'register':registration();return;case 'register-task':registration(t.id);return;case 'connect':registration(null,key);return;case 'connect-task':registration(t.id,key);return;case 'register-next':{const object=C.register(Q);window.NavigationUI?.registerObject(object);break;}case 'reg-step':r.step=Number(key);r.error='';break;
case 'save-return':{if(r){const target=C.returnToTask(Q,{defer:true});if(!target&&C.identityErrors(r).length===0){try{const object=C.register(Q);window.NavigationUI?.registerObject(object);}catch(e){r.error=e.message;paint();return;}}route(target?'task-prep':'plaza');message=target?'已保存对象待补齐信息，其他评测材料保留。':'已保存登记草稿；可从接入对象继续。';paint();return;}break;}
case 'validate':{busy=true;paint();setTimeout(()=>{try{C.validate(Q);if(r.result.ok){if(r.taskId){C.returnToTask(Q);route('task-prep');message='已返回原任务，并选中对象、固定版本和已验证环境。';}else{detailId=r.objectId;detailVersion=C.prepareVersion(Q).id;detailEnv=r.environment;Q.registration=null;route('object-detail');}}}catch(e){r.error=e.message;}finally{busy=false;paint();}},850);return;}
case 'evaluate-object':{const o=C.object(Q,detailId),v=C.version(o,detailVersion);newTask({name:o.name+'评测',type:o.type,objectId:o.id,versionId:v.id,environment:detailEnv});return;}
case 'select-object':{const o=C.object(Q,key),v=o.versions[0];if(!v){registration(t.id,o.id);return;}C.bind(Q,t,o,v,'test');break;}case 'clear-object':if(t.run)throw Error('已冻结任务不能修改。');t.objectId=null;t.versionId=null;C.invalidate(t);break;
case 'defer-object':t.pending={name:pickerQuery,type:t.type};t.savedAt=new Date().toISOString();t.step=1;break;case 'resume':C.resume(Q,t);route('object-create');return;
case 'task-step':t.step=Number(key);window.scrollTo(0,0);break;case 'save-task':t.savedAt=new Date().toISOString();message='任务草稿已保存。';break;case 'preflight':C.preflight(Q,t,suite);break;case 'preflight-next':if(C.preflight(Q,t,suite).ok)t.step=3;break;
case 'repair':if(['data','cases','metrics','suite'].includes(key))t.step=1;else if(key==='environment'&&t.objectId){registration(t.id,t.objectId);return;}else if(key==='capabilities')t.step=2;else t.step=0;break;
case 'confirm':if(S.role!==key)throw Error('当前账号不负责此项确认。');C.confirm(Q,t,key,suite);break;
case 'start':if(S.role!=='engineer')throw Error('请由评测负责人开始评测。');C.start(Q,t,suite);paint();return;
case 'cancel':EvaluationFlow.cancel(t);break;
case 'export':download(t.id+'-评审结果.json',JSON.stringify({synthetic:true,task:t},null,2));message='已导出带合成标记的固定结果。';break;
case 'demo':demoDialog();return;case 'close-demo':document.getElementById('pz-demo').close();break;case 'reset':Q=C.initial();tab='AGENT';query='';pickerQuery='';document.getElementById('pz-demo')?.close();route('overview');return;
}paint();}catch(e){if(r&&S.route==='object-create')r.error=e.message;else message=e.message;paint();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pz]');if(!b||b.disabled)return;e.preventDefault();e.stopPropagation();handle(b.dataset.pz,b.dataset.key||'');},true);
function change(e){const el=e.target,key=el.dataset?.pzField;if(!key||key==='read')return;const value=el.type==='checkbox'?el.checked:el.value,t=C.task(Q),r=Q.registration;let redraw=e.type==='change';
if(key==='galleryQuery'){query=value;redraw=true;}else if(key==='pickerQuery'){pickerQuery=value;redraw=true;}else if(key==='sourceObject'){C.selectSourceObject(Q,value);redraw=true;}else if(key==='detailVersion'){detailVersion=value;}else if(key==='detailEnv'){detailEnv=value;}
else if(key.startsWith('task.')){if(t.run)return;const k=key.slice(5);C.editTask(t,k,value);if(k==='type'){t.objectId=null;t.versionId=null;}t.savedAt=new Date().toISOString();}
else if(key.startsWith('material.')){if(t.run||t.materials.suite)return;t.materials[key.slice(9)]=value;C.invalidate(t);}
else if(key.startsWith('reg.')){const k=key.slice(4);r[k]=value;r.result=null;r.error='';if(k==='source'||k==='type'){r.upstream='';r.versionLabel='';if(k==='type')r.source=value==='MODEL'?'models':'apps';}}
else if(key.startsWith('demo.')){Q.demo[key.slice(5)]=['true','false'].includes(value)?value==='true':value;persist();return;}
persist();if(redraw){const pos=el.selectionStart;paint();const next=document.querySelector(`[data-pz-field="${key}"]`);if(next){next.focus();if(next.setSelectionRange&&typeof pos==='number')next.setSelectionRange(pos,pos);}}}
document.addEventListener('input',change);document.addEventListener('change',change);
// Keep classification cards operable as a standard keyboard tablist.
document.addEventListener('keydown',e=>{const current=e.target.closest('.pz-tab');if(!current||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(C.TYPES),index=keys.indexOf(current.dataset.key);const next=e.key==='Home'?0:e.key==='End'?keys.length-1:(index+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length;handle('tab',keys[next]);});
for(const g of navGroups)g.items=g.items.filter(([id])=>!['demos','evolution','acceptance','prd-review','design'].includes(id)).map(x=>x[0]==='requirements'?['plaza','Agent/模型广场','box']:x);
Object.assign(pages,{overview,tasks,plaza:gallery,'object-detail':detail,'object-create':creation,'task-prep':taskPage,requirements:gallery,new:()=>{setTimeout(()=>newTask(),0);return wrap(title('准备新建评测','正在创建草稿…'));}});
pages.runs=()=>wrap(title('运行与证据','查看固定版本对应的运行状态和证据。')+panel('新版评测运行',table(['任务','状态','操作'],Q.tasks.filter(t=>t.run||t.suitePlan?.manifest).map(t=>[h(t.name),badge(t.suitePlan?(t.suitePlan.report?'已收联调回传':'待回传'):names[t.status]),B('查看运行','open-task',t.id,'ghost')]))))+inheritedRuns();
pages.resources=()=>wrap(panel('对象接入的依赖',table(['来源 / 环境','状态','职责'],[...C.SOURCES.map(s=>[h(s.name),badge(s.connected&&Q.demo.sourceConnected?'已连接（演示）':'待连接',s.connected&&Q.demo.sourceConnected?'good':'warn'),'接入负责人管理目录连接与授权']),...C.ENVIRONMENTS.map(e=>[h(e.name),badge(e.reachable?'可用（演示）':'地址不可达',e.reachable?'good':'warn'),`实际执行身份：${h(e.identity)}`])]))+notice('来源系统负责构建与部署。平台读取既有对象、固定版本和调用配置，并通过执行适配器验证、调用、采集证据。'))+inheritedResources();
const oldRender=render;render=function(){oldRender();if(S.route==='task-prep'&&C.task(Q)?.run)document.querySelectorAll('[data-pz-field^="task."],[data-pz-field^="material."]').forEach(n=>n.disabled=true);document.querySelectorAll('.prd-footer-note').forEach(n=>n.textContent='独立评审副本 · 基线能力保留 · 合成回放，未连接真实服务');document.querySelectorAll('.prototype').forEach(n=>n.textContent='独立评审版 · 合成数据');let ctl=document.getElementById('pz-controls');if(!ctl){ctl=document.createElement('div');ctl.id='pz-controls';ctl.className='pz-demo-control';ctl.innerHTML='<button data-pz="demo">演示条件</button>';document.querySelector('.topactions')?.prepend(ctl);}if(['object-detail','object-create'].includes(S.route))document.querySelector('#nav [data-param="plaza"]')?.classList.add('active');if(S.route==='task-prep')document.querySelector('#nav [data-param="tasks"]')?.classList.add('active');document.querySelectorAll('.footer-note,.prd-footer-note,.demonote').forEach(n=>n.textContent='独立评审副本 · 2026.11.11 · 合成数据，未连接真实服务');const bn=document.getElementById('v2-role-banner');if(bn)bn.innerHTML='<span>独立交互评审版 · 合成数据 · 未连接真实服务</span>';if(['object-detail','object-create'].includes(S.route))document.getElementById('crumb').innerHTML='工作台 / <b>Agent/模型广场</b>';if(S.route==='task-prep')document.getElementById('crumb').innerHTML='评测执行 / <b>评测任务</b>';document.title='AI 评测平台 · 流程整合版 2026.11.11';};
window.PlazaReview={state:()=>Q,persist,paint,route,openTask,newTask,registration,helpers:{B,badge,notice,panel,field,select,kv,table,title,wrap},createTask:(scene,blank,seed={})=>newTask({name:seed.object||seed.name||'未命名评测',goal:seed.goal||'',type:seed.type==='模型'?'MODEL':seed.type==='非Agent应用'?'APPLICATION':'AGENT'})};
if(['requirements','demos','evolution','acceptance','prd-review','design'].includes(S.route))S.route='overview';
render();
})();
